  for(const product of reactionProducts(s.type,spread))nucleus(cx+product.x,cy+product.y,product.p,product.n,product.label,product.mass>5?size*.75:product.mass===4?18:10);
  if(fusion){text('⁴He ≈ 3.5 MeV · neutron ≈ 14.1 MeV',cx,H-112,gold,12,'center');}
