 text(stage,cx,27,gold,13,'center');text('Charge and nucleon number stay balanced',cx,48,muted,12,'center');
 const equation=REACTIONS[s.type].equation.split(' → ');text(equation[0]+' →',cx,H-80,ivory,14,'center');text(equation[1],cx,H-60,ivory,14,'center');
 circle(cx-74,H-32,4,gold);text('Proton',cx-64,H-28,muted,12);circle(cx+20,H-32,4,cyan);text('Neutron',cx+30,H-28,muted,12);
