function drawPendulum(){background();const s=state.pendulum,cx=W/2,top=35,scale=Math.min((H*.52-35)/3,(W/2-28)/3),L=s.length*scale,bx=cx+Math.sin(s.angle)*L,by=top+Math.cos(s.angle)*L;line(cx-42,top,cx+42,top,'#68788a',3);ctx.setLineDash([3,5]);line(cx,top,cx,top+L,'#72869855');ctx.setLineDash([]);ctx.beginPath();ctx.arc(cx,top,L,Math.PI/2-s.angle0*Math.PI/180,Math.PI/2+s.angle0*Math.PI/180);ctx.strokeStyle='#79d2e533';ctx.lineWidth=1;ctx.stroke();line(cx,top,bx,by,'#c3d1d9',2);circle(cx,top,4,gold);halo(bx,by,25,'#79d2e52a');circle(bx,by,11,cyan);text(s.length.toFixed(1)+' m',cx+(bx-cx)/2+14,top+(by-top)/2,muted,12);const gy=H*.78,left=38,right=W-25,gw=right-left;line(left,gy,right,gy,'#51637377');text('ANGLE OVER TIME',left,gy-51,muted,10);text('0°',left-6,gy+3,muted,10,'right');ctx.beginPath();s.history.forEach(([t,a],i)=>{const x=right-(s.time-t)/12*gw,y=gy-a/(Math.PI/2)*42;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.strokeStyle=cyan;ctx.lineWidth=1.8;ctx.stroke();text('last 12 seconds',right,gy+47,muted,10,'right');}
function draw(){if(!ctx)return;if(active==='gravity')syncSpaceControls();ctx.save();if(active==='gravity')drawGravity();else if(active==='compact')drawCompact();else if(active==='nuclear')drawNuclear();else if(active==='waves')drawWaves();else drawPendulum();ctx.restore();}
function advance(dt){
 if(active==='gravity'){
  const s=state.gravity;let remain=dt*.03,steps=0;let events=[];
  while(remain>1e-12&&steps++<1200){events.push(...resolveEncounters(s.bodies));const step=Math.min(remain,safeStep(s.bodies));gravityStep(s.bodies,step);remain-=step;s.time+=step;}
  events.push(...resolveEncounters(s.bodies));s.slowed=remain>1e-12;
  if(events.length){s.mass=s.bodies[0].mass;s.type=s.bodies[0].kind;buildControls();updateInsight();message(events.at(-1).names.join(' + ')+': combined into an unresolved remnant. Mass and momentum retained; the remaining system continues.');}
  const c=cameraCenter(),major=s.bodies.filter(b=>b.mass>.01);let extent=s.view;
  for(const b of major)extent=Math.max(extent,Math.hypot(b.x-c.x,b.y-c.y)*1.3);
  if(s.autoFit&&extent>s.view*1.05){s.view=Math.ceil(extent);buildControls();}
  s.bodies.forEach(b=>{b.trail.push([b.x,b.y]);if(b.trail.length>1800)b.trail.shift();});
 }
 else if(active==='compact'){const s=state.compact,r=(s.type==='blackhole'?SCHWARZSCHILD_KM*s.mass:s.radius)*s.distance;s.time+=dt;s.clock+=dt*clockRate(s.mass,r);}
 else if(active==='nuclear'){const s=state.nuclear;s.progress+=dt/s.duration;if(s.progress>=1){if(s.repeat){s.cycles+=Math.floor(s.progress);s.progress%=1;}else{s.progress=1;setRunning(false);}}}
 else if(active==='waves'){state.waves.time+=dt;}
 else{const s=state.pendulum;let remain=dt;if(!s.history.length)s.history.push([s.time,s.angle]);while(remain>1e-9){const step=Math.min(.005,remain);pendulumStep(s,step,s.length,s.g,s.damping);remain-=step;s.time+=step;if(s.time-s.history.at(-1)[0]>=.025-1e-9)s.history.push([s.time,s.angle]);}while(s.history.length&&s.history[0][0]<s.time-12)s.history.shift();}
}
function frame(t){const dt=last?Math.min((t-last)/1000,.25):0;last=t;if(!document.hidden&&running)advance(dt*speed);if(!document.hidden)draw();if(t-readoutTick>120){updateReadouts();readoutTick=t;}requestAnimationFrame(frame);}
$('#play').onclick=()=>{if(placing){placing=false;$('#stage').classList.remove('placing');message('');}setRunning(!running);};$('#reset').onclick=resetLab;$('#play-speed').onchange=e=>{speed=+e.target.value;};
$('#challenge-button').onclick=()=>{if(active==='gravity'){startBinary();}else if(active==='compact'){Object.assign(state.compact,{type:'blackhole',mass:5,distance:1.2,time:0,clock:0});}else if(active==='nuclear'){state.nuclear.type='fission';state.nuclear.progress=0;state.nuclear.cycles=0;}else if(active==='waves'){state.waves.phase=180;}else {state.pendulum.g=1.62;releasePendulum();}buildControls();updateInsight();updateReadouts();setRunning(true);$('#laboratory').scrollIntoView({behavior:reduceMotion?'auto':'smooth'});};
$('#cinema').onclick=()=>{const on=document.body.classList.toggle('focus-mode');$('#cinema').setAttribute('aria-pressed',String(on));$('#cinema').innerHTML=on?'× <span>Exit focus</span>':'⤢ <span>Focus</span>';$('#cinema').title=on?'Exit focus mode':'Expand the laboratory';};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('focus-mode'))$('#cinema').click();});

