 const view=$('#view');if(view&&view.value!==String(s.view)){const choices=[[2.1,'Inner planets'],[7,'To Jupiter'],[35,'Whole planetary system'],[150,'Deep space'],[1000,'Wide encounter']];if(!choices.some(([v])=>v===s.view))choices.push([s.view,'Custom zoom']);view.innerHTML=choices.map(([v,label])=>`<option value="${v}">${label} · ${v.toLocaleString(undefined,{maximumFractionDigits:2})} AU</option>`).join('');view.value=String(s.view);}
 $('#space-scene').value=s.scene;$('#space-scale').textContent=map?'View radius: '+Math.round(s.galaxyView).toLocaleString()+' light-years':'View radius: '+s.view.toLocaleString(undefined,{maximumFractionDigits:2})+' AU';
