function fitSpace(){const s=state.gravity;recenterSpace();if(s.scene==='galaxy')s.galaxyView=60000;else{const c=cameraCenter();s.view=Math.max(2.1,...s.bodies.map(b=>Math.hypot(b.x-c.x,b.y-c.y)*1.3));s.autoFit=true;buildControls();}draw();}
