 for(let radius=10000;radius<=50000;radius+=10000){ctx.beginPath();ctx.arc(cx,cy,radius*scale,0,Math.PI*2);ctx.strokeStyle=radius===50000?'#8fa2b6':'#324458';ctx.lineWidth=1;ctx.stroke();}
