canvas.addEventListener('pointerdown',e=>{if(active!=='gravity')return;if(!placing){dragPointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);return;}const r=canvas.getBoundingClientRect(),s=state.gravity,scale=Math.min(W,H-70)/(2*s.view);const c=cameraCenter(),p=s.bodies[0];placeVisitor((e.clientX-r.left-W/2)/scale+c.x-p.x,-(e.clientY-r.top-H/2-5)/scale+c.y-p.y);});
const observer=new ResizeObserver(()=>{const r=canvas.getBoundingClientRect();W=r.width;H=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0);draw();});observer.observe(canvas);
